cy.xpath(_Selector.selectors.cart_btn).click();
const quantity = 5;
cy.xpath(_Selector.selectors.item_price).eq(1).invoke('text').then(priceText => {
  const itemPrice = parseFloat(priceText.replace('$', ''));
  // FORCE reset quantity properly
  cy.xpath(_Selector.selectors.quantity).eq(1).clear().type('{selectall}{backspace}' + quantity);
  cy.xpath(_Selector.selectors.update_btn).click();
  cy.wait(4000);
  const expectedTotal = itemPrice * quantity;
  cy.xpath(_Selector.selectors.total_cost).eq(1).invoke('text').then(totalText => {
    const uiTotal = parseFloat(totalText.replace('$', ''));
    cy.log('UI Total: ' + uiTotal);
    cy.log('Expected Total: ' + expectedTotal);
    expect(uiTotal).to.equal(expectedTotal);
  });
});

